/* Concours Maroc — practice app: content loading.
 * JSON files are generated by the site build into /data. Question banks are
 * fetched lazily, one subject at a time, and cached by the service worker so
 * that the trainer keeps working offline after a first visit. */
(function (global) {
  'use strict';

  var host = document.getElementById('cm-app');
  var BASE = (host && host.getAttribute('data-data')) || 'data/';
  var cache = {};
  var loaded = {};

  function getJson(path) {
    if (cache[path]) return cache[path];
    var p = global.fetch(BASE + path).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status + ' — ' + path);
      return res.json();
    });
    cache[path] = p;
    p.catch(function () { delete cache[path]; });
    return p;
  }

  var Loader = {
    base: BASE,
    manifest: function () { return getJson('manifest.json'); },
    concours: function () { return getJson('concours.json'); },
    sources: function () { return getJson('sources.json').catch(function () { return { sources: [] }; }); },
    i18n: function (code) { return getJson('i18n/' + code + '.json'); },
    bank: function (cat) { return getJson('questions/' + cat + '.json'); },

    /* Loads the banks of the given subjects that are not loaded yet and
       resolves with the newly loaded questions. */
    ensure: function (cats) {
      var need = (cats || []).filter(function (c) { return c && !loaded[c]; });
      return Promise.all(need.map(function (c) {
        return Loader.bank(c).then(function (b) {
          loaded[c] = true;
          return b.questions || [];
        }).catch(function (e) {
          console.warn('[data] bank ' + c + ' unavailable:', e.message);
          return [];
        });
      })).then(function (lists) { return [].concat.apply([], lists); });
    },

    isLoaded: function (c) { return !!loaded[c]; }
  };

  global.CM = global.CM || {};
  global.CM.data = Loader;
})(window);
